INSERT INTO `tag` (`name`, `status`) SELECT 'Arduino', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Arduino') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Electronics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Electronics') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Robotics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Robotics') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'arduino-electronics-class-august-2017');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Arduino', 'Electronics', 'Robotics', 'WSQ');

-- Seed the like count (same `likes < 100` guard as the sibling posts).
UPDATE `mmd_blog_post` SET `likes` = 128 WHERE `url_key` = 'arduino-electronics-class-august-2017' AND `likes` < 100;
